struct HelpSystemState
{
    // 0: Top level / Book
    // 1: Chapter
    // 2: Verse
    // 3: Text
    u8 level;

    // enum HelpSystemTopics
    u8 topic;
    u8 chapter;
    u8 verse;

    // Where the player's cursor was at Book level
    u8 scrollBook;

    // Where the player's cursor was at Chapter level
    u8 scrollChapter;

    // Where the player's cursor was at Verse level
    u8 scrollVerse;
};

